SET NOCOUNT ON;
DECLARE @Results TABLE(Test nvarchar(200));
DECLARE @Stamp uniqueidentifier=(SELECT SecurityStamp FROM Customer_Logins WHERE AccountID=2),@Batch uniqueidentifier,@ID int,@ID2 int,@Decision xml;
DECLARE @Submitted TABLE(Batch_ID uniqueidentifier);
INSERT @Submitted EXEC Customer_WorkGuide @AccountID=2,@Stamp=@Stamp,@Brand=1,@Section='submit',@Categories=N'<items><item id="1"/><item id="2"/></items>',@Reason=N'Customer integration test';
SELECT @Batch=Batch_ID FROM @Submitted;
IF (SELECT COUNT(*) FROM Work_Guide_Access_Requests WHERE Batch_ID=@Batch AND Customer_ID=2 AND User_ID IS NULL)<>2 THROW 51999,'Customer request did not enter existing workflow.',1;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,1) WHERE Can_View_Document=1) THROW 51999,'Pending request granted permission.',1;
INSERT @Results VALUES('Customer requests use existing work-guide workflow; pending requests grant nothing');
BEGIN TRY EXEC Customer_WorkGuide @AccountID=2,@Stamp=@Stamp,@Brand=1,@Section='submit',@Categories=N'<items><item id="1"/></items>',@Reason=N'duplicate';THROW 51999,'Duplicate request allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51104 THROW;END CATCH;
INSERT @Results VALUES('Duplicate pending requests blocked');
SELECT @ID=ID FROM Work_Guide_Access_Requests WHERE Batch_ID=@Batch AND Category_ID=1;
SELECT @ID2=ID FROM Work_Guide_Access_Requests WHERE Batch_ID=@Batch AND Category_ID=2;
SET @Decision=CONCAT('<items><item id="',@ID,'" status="A" role="1" note="Approved"/><item id="',@ID2,'" status="R" role="0" note="Rejected with reason"/></items>');
BEGIN TRY EXEC Review_Work_Guide_Access_Request 2,@Batch,@Decision;THROW 51999,'Non-admin approved',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51100 THROW;END CATCH;
DECLARE @Reviewed TABLE(Reviewed_Count int);INSERT @Reviewed EXEC Review_Work_Guide_Access_Request 1,@Batch,@Decision;
IF NOT EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,1) WHERE ID=1 AND Can_View_Document=1) OR EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,1) WHERE ID=2 AND Can_View_Document=1) THROW 51999,'Mixed customer approval failed',1;
IF EXISTS(SELECT 1 FROM Work_Guide_User_Category_Roles WHERE User_ID=2) THROW 51999,'Customer IDs leaked to employee grants',1;
INSERT @Results VALUES('Existing admin review approves/rejects customer requests without employee-ID collision');
BEGIN TRY EXEC Review_Work_Guide_Access_Request 1,@Batch,@Decision;THROW 51999,'Re-reviewed request allowed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51106 THROW;END CATCH;
INSERT @Results VALUES('Already reviewed request cannot be approved again');
EXEC Customer_WorkGuideAdmin @Actor=1,@Section='add',@AccountID=2,@Brand=2,@Role=1,@Categories=N'<items><item id="3"/></items>';
IF NOT EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,2) WHERE Can_View_Document=1) THROW 51999,'Existing admin multi-brand grant failed',1;
EXEC Customer_WorkGuideAdmin @Actor=1,@Section='edit',@AccountID=2,@Brand=2,@Role=2,@OldRole=1,@Categories=N'<items><item id="3"/></items>';
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,2) WHERE Can_Download_Document=1) THROW 51999,'Role edit failed',1;
EXEC Customer_WorkGuideAdmin @Actor=1,@Section='delete',@AccountID=2,@Brand=2,@Role=2;
IF EXISTS(SELECT 1 FROM Customer_Guide_Effective(2,2) WHERE Can_View_Document=1) THROW 51999,'Group revoke failed',1;
INSERT @Results VALUES('Existing grouped administration grants, edits and revokes customer multi-brand access');
DECLARE @FeedbackID int=(SELECT MIN(RequestID) FROM Customer_Portal_Feedback WHERE AccountID=1);
BEGIN TRY EXEC Customer_FeedbackDetail 2,@Stamp,@FeedbackID;THROW 51999,'Other customer complaint exposed',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
IF NOT EXISTS(SELECT 1 FROM Customer_Portal_Activity WHERE Action='feedback' AND FeedbackTypeTitle=N'شكوى' AND Note LIKE N'%شكوى%') THROW 51999,'Feedback type missing from audit',1;
INSERT @Results VALUES('Complaint details are owner-scoped; audit names the submitted feedback type');
SELECT * FROM @Results;
